 for(let y=0;y<IH;y++)for(let x=0;x<IW;x++){const i=y*IW+x;if(DT[i]===0)continue;let d=DT[i];if(x>0)d=Math.min(d,DT[i-1]+1);if(y>0)d=Math.min(d,DT[i-IW]+1);if(x>0&&y>0)d=Math.min(d,DT[i-IW-1]+1.414);if(x<IW-1&&y>0)d=Math.min(d,DT[i-IW+1]+1.414);DT[i]=d;}
