/* --- the brain --- */
function vsField(){if(VS_D&&VS_DID===curLvl.id)return VS_D;var GS=4,GW=Math.ceil(IW/GS),GH=Math.ceil(IH/GS),D=new Float32Array(GW*GH);D.fill(1e9);var cgx=Math.round(cup.u*IW/GS),cgy=Math.round(cup.v*IW/GS);
 if(!window.__onfairAt(cgx*GS/IW,cgy*GS/IW)){var bd=1e9,bx=cgx,by=cgy;for(var ay=-5;ay<=5;ay++)for(var ax=-5;ax<=5;ax++){var nx=cgx+ax,ny=cgy+ay;if(nx<0||ny<0||nx>=GW||ny>=GH)continue;if(!window.__onfairAt(nx*GS/IW,ny*GS/IW))continue;var dd=ax*ax+ay*ay;if(dd<bd){bd=dd;bx=nx;by=ny;}}cgx=bx;cgy=by;}
 var q=[[cgx,cgy]];D[cgy*GW+cgx]=0;var head=0;while(head<q.length){var c=q[head++],gx=c[0],gy=c[1],d0=D[gy*GW+gx];var nb=[[1,0],[-1,0],[0,1],[0,-1]];for(var k=0;k<4;k++){var nx2=gx+nb[k][0],ny2=gy+nb[k][1];if(nx2<0||ny2<0||nx2>=GW||ny2>=GH)continue;var ni=ny2*GW+nx2;if(D[ni]<=d0+1)continue;if(!window.__onfairAt(nx2*GS/IW,ny2*GS/IW))continue;D[ni]=d0+1;q.push([nx2,ny2]);}}
 VS_D={D:D,GS:GS,GW:GW,GH:GH};VS_DID=curLvl.id;return VS_D;}
function vsPathD(u,v){var F=vsField(),best=1e9,gx=Math.round(u*IW/F.GS),gy=Math.round(v*IW/F.GS);for(var ay=-1;ay<=1;ay++)for(var ax=-1;ax<=1;ax++){var nx=gx+ax,ny=gy+ay;if(nx<0||ny<0||nx>=F.GW||ny>=F.GH)continue;best=Math.min(best,F.D[ny*F.GW+nx]+Math.hypot(ax,ay));}return best;}
function vsEval(dx,dy,pw){var pts=predictPath(dx,dy,pw,900);var last=pts[pts.length-1];var sunkQ=!!window.__predSunk;   /* TRUE capture in the sim - never a lip-out counted as a sink */return {d:sunkQ?-1:vsPathD(last[0],last[1]),sunk:sunkQ,u:last[0],v:last[1]};}
/* GOD BRAIN (owner 22 Sep: "Oracle cannot miss simple shots"): 1) the exact direct line at fine power - a God takes the clean putt when it exists; 2) a small fan around it; 3) only if the line is walled off, a full 5-degree sweep; 4) refine around the best. Picks the most DIRECT sinking shot at the GENTLEST power. */
function vsPlanGod(){var cands=[],sinks=[],a0=Math.atan2(cup.v-ball.v,cup.u-ball.u)*180/Math.PI;
 function ev(a,pw){var dx=Math.cos(a*Math.PI/180),dy=Math.sin(a*Math.PI/180),r=vsEval(dx,dy,pw),c={a:a,pw:pw,d:r.d,sunk:r.sunk,u:r.u,v:r.v};cands.push(c);if(r.sunk)sinks.push(c);return c;}
 var pws=[];for(var p=0.10;p<=1.0001;p+=0.03)pws.push(+p.toFixed(3));
 for(var i=0;i<pws.length;i++)ev(a0,pws[i]);
 if(!sinks.length){for(var da=1;da<=6;da++)for(var sg=-1;sg<=1;sg+=2)for(var j=0;j<pws.length;j+=2)ev(a0+sg*da,pws[j]);}
 if(!sinks.length){var pw8=[0.12,0.2,0.3,0.42,0.56,0.72,0.86,1.0];for(var a=0;a<360;a+=5)for(var k=0;k<pw8.length;k++)ev(a,pw8[k]);}
 var seeds=(sinks.length?sinks.slice():cands.slice().sort(function(p,q){return p.d-q.d;})).slice(0,3);
 for(var s=0;s<seeds.length;s++){var sd=seeds[s];for(var d2=-3;d2<=3;d2++)for(var dp=-0.04;dp<=0.0401;dp+=0.02)ev(sd.a+d2,Math.max(0.1,Math.min(1,sd.pw+dp)));}
 var dev=function(c){return Math.abs(((c.a-a0+540)%360)-180);};
 if(sinks.length){sinks.sort(function(p,q){return (dev(p)-dev(q))||(p.pw-q.pw);});return {pick:sinks[0],cands:cands};}
 cands.sort(function(p,q){return (p.d-q.d)||(p.pw-q.pw);});return {pick:cands[0],cands:cands};}
function vsPlan(cfg){try{var cands=[],a,pw;var powers=[0.14,0.22,0.32,0.5,0.72,1.0];
 if(cfg.brain==="straight"){var a0=Math.atan2(cup.v-ball.v,cup.u-ball.u)*180/Math.PI;var offs=[-10,-5,0,5,10];for(var i=0;i<offs.length;i++)for(var j=0;j<powers.length;j++){a=a0+offs[i];pw=powers[j];var dx=Math.cos(a*Math.PI/180),dy=Math.sin(a*Math.PI/180);var r=vsEval(dx,dy,pw);cands.push({a:a,pw:pw,d:r.d,sunk:r.sunk,u:r.u,v:r.v});}
  /* the straight line is walled off (dogleg): the rookie looks around clumsily - a coarse 20-degree sweep */
  var cur0=vsPathD(ball.u,ball.v),best0=cands.slice().sort(function(p,q){return p.d-q.d;})[0];if(best0&&!best0.sunk&&best0.d>cur0-Math.max(8,cur0*0.3)){for(a=0;a<360;a+=20)for(var j3=0;j3<powers.length;j3++){pw=powers[j3];var dx3=Math.cos(a*Math.PI/180),dy3=Math.sin(a*Math.PI/180);var r3=vsEval(dx3,dy3,pw);cands.push({a:a,pw:pw,d:r3.d,sunk:r3.sunk,u:r3.u,v:r3.v});}}}
 else if(cfg.brain==="best"){var _g=vsPlanGod();cands=_g.cands;}
 else{var _st=(typeof MOD!=="undefined"&&MOD.fog&&MOD.owner==="you")?30:10;for(a=0;a<360;a+=_st)for(var j2=0;j2<powers.length;j2++){pw=powers[j2];var dx2=Math.cos(a*Math.PI/180),dy2=Math.sin(a*Math.PI/180);var r2=vsEval(dx2,dy2,pw);cands.push({a:a,pw:pw,d:r2.d,sunk:r2.sunk,u:r2.u,v:r2.v});}}
 cands.sort(function(p,q){return (p.d-q.d)||(p.pw-q.pw);});var pick=(cfg.brain==="best"&&typeof _g!=="undefined")?_g.pick:cands[0];
 if(cfg.brain==="search3"){var top=cands.slice(0,3);pick=top[Math.floor(Math.random()*top.length)];}
 var curD=vsPathD(ball.u,ball.v);if(!pick.sunk&&pick.d>=curD-1){/* stuck against a wall: take the candidate that moves the ball the most */var esc=null;for(var k=0;k<cands.length;k++){var c=cands[k],mv=Math.hypot(c.u-ball.u,c.v-ball.v);if(mv<0.12)continue;if(!esc||c.d<esc.d)esc=c;}if(esc)pick=esc;}
 /* execution wobble: the plan is good, the hands are human */
 var aErr=(Math.random()*2-1)*(cfg.aim+((typeof MOD!=="undefined"&&MOD.wobble&&MOD.owner==="you")?MOD.wobble:0)),pErr=1+(Math.random()*2-1)*cfg.pow;var af=pick.a+aErr,pf=Math.max(0.12,Math.min(1,pick.pw*pErr));if(cfg.duff&&Math.random()<cfg.duff)pf*=0.45;
 return {dx:Math.cos(af*Math.PI/180),dy:Math.sin(af*Math.PI/180),pw:pf};}catch(e){return null;}}
/* headless planner check for QA: returns strokes the given opponent needs on the CURRENT hole from the tee (no animation, state restored) */
window.__vsProbe=function(key){var cfg=VS_LEVELS[key];if(!cfg||!curLvl)return null;var sb=ball,sv={x:vel.x,y:vel.y},ss=shots,su=sunk,si=sinking;ball={u:tee.u,v:tee.v};vel={x:0,y:0};var n=0,done=false,guard=0;while(!done&&n<PAR+3&&guard++<12){var plan=vsPlan(cfg);if(!plan)break;n++;var pts=predictPath(plan.dx,plan.dy,plan.pw,900);var last=pts[pts.length-1];if(Math.hypot(last[0]-cup.u,last[1]-cup.v)<whirlR*1.05){done=true;break;}ball={u:last[0],v:last[1]};}ball=sb;vel=sv;shots=ss;sunk=su;sinking=si;return {strokes:n,sunk:done,par:PAR};};
/* --- roster HUD --- */
function vsRoundStat(p){var s=0,par=0;if(!VS)return{shots:0,vpar:0};for(var i=0;i<LEVELS.length;i++){var L=LEVELS[i];if(L.world!==curWorldN||L.status!=="ready")continue;var hh=VS.holes[L.id];if(hh&&hh[p]!=null){s+=hh[p];par+=(L.par||3);}else if(curLvl&&L.id===curLvl.id){var live=(VS.active===p)?shots:(VS.pb&&VS.pb[p]?(VS.pb[p].shots||0):0);if(live>0){s+=live;par+=(L.par||3);}}}return {shots:s,vpar:s-par};}
function vpStr(v){return v===0?"E":(v<0?String(v):"+"+v);}
