 const grow=(seed)=>{const R=(0.42*IW)|0,bx0=Math.max(1,seed[0]-R),bx1=Math.min(IW-2,seed[0]+R),by0=Math.max(1,seed[1]-R),by1=Math.min(IH-2,seed[1]+R);const vis=new Uint8Array(IW*IH);const st=[seed[1]*IW+seed[0]];vis[st[0]]=1;const blob=[];while(st.length){const i=st.pop();const x=i%IW,y=(i/IW)|0;if(x<=bx0||x>=bx1||y<=by0||y>=by1)return null;blob.push(i);const nb=[i-1,i+1,i-IW,i+IW];for(const n of nb){if(vis[n])continue;vis[n]=1;if(pass(n))st.push(n);}}return blob;};
 const sx0=Math.max(1,Math.min(IW-2,(o.u*IW)|0)),sy0=Math.max(1,Math.min(IH-2,(o.v*IW)|0));
 let best=null;const tried=new Set();
 for(let r=0;r<IW*0.14&&(!best||best.length<400);r+=6)for(let a=0;a<360;a+=20){const x=(sx0+Math.cos(a*0.01745)*r)|0,y=(sy0+Math.sin(a*0.01745)*r)|0;if(x<=0||y<=0||x>=IW-1||y>=IH-1)continue;const i=y*IW+x;if(tried.has(i)||!pass(i))continue;tried.add(i);const bl=grow([x,y]);if(bl&&bl.length>=60&&(!best||bl.length>best.length))best=bl;if(r===0)break;}
 if(!best)return false;const blob=best;
 let mx=0,my=0;for(const i of blob){mx+=i%IW;my+=(i/IW)|0;}mx/=blob.length;my/=blob.length;
