 for(let d=0;d<9;d++){const nf=[];for(const i of frontier)for(const n of [i-1,i+1,i-IW,i+IW]){if(inB[n]&&!band[n]){band[n]=1;nf.push(n);}}frontier=nf;if(!nf.length)break;}
 const pts=[];for(const i of blob){if(!band[i])continue;const x=i%IW,y=(i/IW)|0;const r=dd[i*4],g=dd[i*4+1],b=dd[i*4+2],mxv=Math.max(r,g,b),mn=Math.min(r,g,b);if(!(mxv-mn<64&&mxv>70&&!(g>r+8&&g>b+8)))continue;
  const vx=x-mx,vy=y-my;let outer=false;for(const [dx,dy] of [[1,0],[-1,0],[0,1],[0,-1]]){for(let k=1;k<=12;k++){const nx=x+dx*k,ny=y+dy*k;if(nx<=0||ny<=0||nx>=IW-1||ny>=IH-1)break;if(!inB[ny*IW+nx]){if(dx*vx+dy*vy>0)outer=true;break;}}if(outer)break;}
  if(outer)pts.push([x,y]);}
 if(pts.length<12)return false;
 /* centred least-squares axis-aligned ellipse; fall back to mid-range extents */
