function drawFogOver(){if(typeof OBJS==="undefined"||(typeof EDIT!=="undefined"&&EDIT))return;for(const o of OBJS){if(o.t!=="fog")continue;const S2=scl(),cx=toX(o.u),cy=toY(o.v),L=o.sx*S2,W=o.sy*S2,tt=objT;g.save();g.translate(cx,cy);for(let k=0;k<3;k++){const ph=tt*0.4+k*2.1,dx=Math.cos(ph)*L*0.12,dy=Math.sin(ph*0.8)*W*0.12,rr=1+0.06*Math.sin(tt*0.9+k);const gr=g.createRadialGradient(dx,dy,0,dx,dy,Math.max(L,W)*rr);gr.addColorStop(0,"rgba(232,238,242,0.96)");gr.addColorStop(0.55,"rgba(225,232,238,0.9)");gr.addColorStop(1,"rgba(220,228,235,0)");g.fillStyle=gr;g.beginPath();g.ellipse(dx,dy,L*rr,W*rr,0,0,7);g.fill();}g.restore();}}
function drawObjs(){const __base=(g.getTransform?g.getTransform():null);for(const o of OBJS){if(o.got)continue;if(o.t==="edge"&&o.sys&&!(typeof EDIT!=="undefined"&&EDIT))continue;const P=o.p||{},cx=toX(o.t==="hole"?cup.u:o.u),cy=toY(o.t==="hole"?cup.v:o.v),S=scl(),L=o.sx*S,W=o.sy*S,fx=Math.cos(o.a),fy=Math.sin(o.a);g.save();g.translate(cx,cy);pieceArt(o,L,W,S,objT);
    g.restore();if(__base&&g.setTransform)g.setTransform(__base);}}
