const $e=id=>document.getElementById(id);
const toU=x=>(x-rect.x-rect.w/2)/scl()+cam.cx, toV=y=>(y-rect.y-rect.h/2)/scl()+cam.cy;
function edefP(t){const p={};(EPOOL[t].sliders||[]).forEach(s=>p[s.k]=0.5);return p;}
function eadd(t){if(t==="hole"||t==="tee")OBJS=OBJS.filter(o=>o.t!==t);const d=EPOOL[t].def,hs=t==="hole"?WHIRLR:0;OBJS.push({t,u:t==="hole"?cup.u:(t==="tee"?tee.u:cam.cx),v:t==="hole"?cup.v:(t==="tee"?tee.v:cam.cy),sx:hs||d.sx,sy:hs||d.sy,a:-Math.PI/2,p:edefP(t)});esel=OBJS.length-1;erefresh();epalHide();}
function holeR(u,v){if(!MASK)return WHIRLR;const im=(pu,pv)=>{const px=Math.round(pu*IW),py=Math.round(pv*IW);if(px<0||py<0||px>=IW||py>=IH)return false;return MASK[py*IW+px]===1;};let r=WHIRLR;for(;r>0.016;r-=0.002){let ok=true;for(let a=0;a<40;a++){const th=a/40*6.2832;if(!im(u+Math.cos(th)*r*1.04,v+Math.sin(th)*r*0.5*1.04)){ok=false;break;}}if(ok)break;}return r;}
function echev(L,W){const aw=Math.min(W*0.6,L*0.75);let ah=Math.min(W*0.42,L*0.3),gap=ah*1.7;if(gap+ah>L*0.82){const k=L*0.82/(gap+ah);gap*=k;ah*=k;}for(let ci=0;ci<3;ci++){const off=(ci-1)*gap;g.beginPath();g.moveTo(off-ah,aw);g.lineTo(off+ah,0);g.lineTo(off-ah,-aw);g.lineWidth=Math.max(2.5,Math.min(aw,ah)*0.7);g.lineJoin="round";g.strokeStyle="#fff";g.stroke();}}
function edrawObj(o,selected){if(o.sys)return;if(o.t==="island"&&!(o.p&&o.p.poly)&&!(o.p&&o.p.auto===false)&&(o._fu===undefined||Math.hypot(o.u-o._fu,o.v-o._fv)>0.012)){if(!autoIsland(o)){o._fu=o.u;o._fv=o.v;}}const P=EPOOL[o.t],cx=toX(o.u),cy=toY(o.v),S=scl(),L=o.sx*S,W=o.sy*S,sp=o.p||{};
 g.save();g.translate(cx,cy);g.globalAlpha=0.9;
g.globalAlpha=1;pieceArt(o,L,W,S,T);
 g.restore();g.globalAlpha=1;
 let lbl=P.name;if(o.t==="portal"){const idx=OBJS.filter((q,qi)=>q.t==="portal"&&qi<=OBJS.indexOf(o)).length-1;lbl+=" "+String.fromCharCode(65+idx);}
 if(o.t!=="slope"){g.fillStyle=P.col;g.font="700 11px -apple-system,sans-serif";g.textAlign="center";g.fillText(lbl,cx,cy-W-9);}
 if(selected){const HO=20;g.save();g.translate(cx,cy);g.rotate(o.a);g.setLineDash([5,5]);g.lineWidth=2;g.strokeStyle="#fff";g.strokeRect(-L,-W,2*L,2*W);g.setLineDash([]);
   /* SIZE handle: square with a diagonal double-arrow + a "SIZE" tag */
   g.beginPath();g.rect(L+HO-11,W+HO-11,22,22);g.fillStyle="#fff";g.fill();g.lineWidth=2;g.strokeStyle="#111";g.stroke();g.lineCap="round";g.lineWidth=2.2;g.beginPath();g.moveTo(L+HO-6,W+HO+6);g.lineTo(L+HO+6,W+HO-6);g.moveTo(L+HO+1,W+HO-6);g.lineTo(L+HO+6,W+HO-6);g.lineTo(L+HO+6,W+HO-1);g.moveTo(L+HO-1,W+HO+6);g.lineTo(L+HO-6,W+HO+6);g.lineTo(L+HO-6,W+HO+1);g.stroke();
   g.save();g.translate(L+HO,W+HO+25);g.rotate(-o.a);g.fillStyle="rgba(10,12,9,.82)";g.beginPath();if(g.roundRect)g.roundRect(-22,-8,44,16,8);else g.rect(-22,-8,44,16);g.fill();g.fillStyle="#fff";g.font="800 10px -apple-system,sans-serif";g.textAlign="center";g.textBaseline="middle";g.fillText("SIZE",0,0.5);g.restore();
   if(o.t!=="hole"&&o.t!=="tee"){/* TURN handle: circle with a curved arrow + a "TURN" tag */
    g.beginPath();g.moveTo(0,-W);g.lineTo(0,-(W+HO+18));g.strokeStyle="#fff";g.lineWidth=2;g.stroke();g.beginPath();g.arc(0,-(W+HO+18),12,0,7);g.fillStyle="#fff";g.fill();g.lineWidth=2;g.strokeStyle="#111";g.stroke();
    g.beginPath();g.arc(0,-(W+HO+18),6,0.7,5.4);g.lineWidth=2;g.stroke();g.beginPath();g.moveTo(2.5,-(W+HO+18)-6.5);g.lineTo(7,-(W+HO+18)-4);g.lineTo(3.5,-(W+HO+18)-1);g.closePath();g.fillStyle="#111";g.fill();
    g.save();g.translate(0,-(W+HO+18)-25);g.rotate(-o.a);g.fillStyle="rgba(10,12,9,.82)";g.beginPath();if(g.roundRect)g.roundRect(-22,-8,44,16,8);else g.rect(-22,-8,44,16);g.fill();g.fillStyle="#fff";g.font="800 10px -apple-system,sans-serif";g.textAlign="center";g.textBaseline="middle";g.fillText("TURN",0,0.5);g.restore();}
   g.textBaseline="alphabetic";g.restore();}}
function edraw(){for(let i=0;i<OBJS.length;i++)edrawObj(OBJS[i],i===esel);
 if(!OBJS.some(o=>o.t==="hole")){g.save();g.fillStyle="rgba(255,255,255,.55)";g.font="700 13px -apple-system,sans-serif";g.textAlign="center";g.fillText("Tap + Add, then Hole, to set the cup",innerWidth/2,rect.y+30);g.restore();}}
function etoLocal(o,x,y){const dx=x-toX(o.u),dy=y-toY(o.v),ax=Math.cos(o.a),ay=Math.sin(o.a),px=-Math.sin(o.a),py=Math.cos(o.a);return [dx*ax+dy*ay,dx*px+dy*py];}
function ehandleAt(o,x,y){const S=scl(),L=o.sx*S,W=o.sy*S,ax=Math.cos(o.a),ay=Math.sin(o.a),px=-Math.sin(o.a),py=Math.cos(o.a),HO=20;
 const rhx=toX(o.u)+ax*(L+HO)+px*(W+HO),rhy=toY(o.v)+ay*(L+HO)+py*(W+HO);
 const rox=toX(o.u)-px*(W+HO+18),roy=toY(o.v)-py*(W+HO+18);
 if(o.t!=="hole"&&o.t!=="tee"&&Math.hypot(x-rox,y-roy)<24)return "rotate";
 if(Math.hypot(x-rhx,y-rhy)<24)return "resize";
 const l=etoLocal(o,x,y);if(Math.abs(l[0])<L&&Math.abs(l[1])<W)return "move";return "";}
c.addEventListener("pointerdown",e=>{if(!EDIT)return;const p=ptr(e),x=p.x,y=p.y;
 if(esel>=0){const h=ehandleAt(OBJS[esel],x,y);if(h){emode=h;estart={x,y,o:Object.assign({},OBJS[esel])};return;}}
 for(let i=OBJS.length-1;i>=0;i--){if(OBJS[i].sys||OBJS[i].t==="slope")continue;const l=etoLocal(OBJS[i],x,y),S=scl(),L=OBJS[i].sx*S,W=OBJS[i].sy*S;if(Math.abs(l[0])<L+6&&Math.abs(l[1])<W+6){esel=i;emode="move";estart={x,y,o:Object.assign({},OBJS[i])};erefresh();return;}}
 esel=-1;emode="";erefresh();});
c.addEventListener("pointermove",e=>{if(!EDIT||!emode||esel<0)return;e.preventDefault();const o=OBJS[esel],p=ptr(e),x=p.x,y=p.y;
 if(emode==="move"){o.u=estart.o.u+(toU(x)-toU(estart.x));o.v=estart.o.v+(toV(y)-toV(estart.y));}
 else if(emode==="rotate"){o.a=Math.atan2(y-toY(o.v),x-toX(o.u));}
 else if(emode==="resize"){const l=etoLocal(o,x,y),S=scl();let sx=Math.max(0.02,Math.abs(l[0])/S),sy=Math.max(0.02,Math.abs(l[1])/S);const sh=EPOOL[o.t].shape;if(sh==="circle"||sh==="spinner"||sh==="portal"||sh==="coin"||sh==="gem"||sh==="gopher"||sh==="geyser"||sh==="pend"||sh==="hole"||sh==="cupmag")sx=sy=Math.max(sx,sy);if(o.t==="hole"){sx=sy=Math.max(0.028,Math.min(0.08,Math.max(sx,sy)));}if(o.t==="tee"){sx=sy=0.03;}o.sx=sx;o.sy=sy;}
},{passive:false});
c.addEventListener("pointerup",()=>{if(EDIT){emode="";estart=null;}});
function ecount(){const el=$e("ecount");if(el)el.textContent=OBJS.length+" piece(s)"+(OBJS.some(o=>o.t==="hole")?"":" - add the Hole");}
function emsg(s){const m=$e("emsg");if(m)m.textContent=s;const t=$e("etoast");if(t){t.textContent=s;t.classList.add("show");clearTimeout(emsg._t);emsg._t=setTimeout(()=>t.classList.remove("show"),4500);}}
function erefresh(){const pnl=$e("eprops");if(!pnl)return;
 if(esel<0||!EDIT){pnl.style.display="none";ecount();return;}
 pnl.style.display="block";const o=OBJS[esel],P=EPOOL[o.t];$e("epname").textContent=P.name;$e("epdesc").textContent=P.desc;
 const sc=$e("esliders");sc.innerHTML="";o.p=o.p||{};(P.sliders||[]).forEach(s=>{const row=document.createElement("div");row.className="esrow";const lab=document.createElement("span");lab.className="eslab";lab.textContent=s.label;const inp=document.createElement("input");inp.type="range";inp.min=0;inp.max=100;if(s.k==="hue")inp.className="hue";inp.value=Math.round((o.p[s.k]==null?0.5:o.p[s.k])*100);inp.oninput=()=>{o.p[s.k]=inp.value/100;};row.appendChild(lab);row.appendChild(inp);sc.appendChild(row);});
 ecount();}
function ecfg(){return OBJS.filter(o=>o.t!=="island").map(o=>{const r={t:o.t,u:+o.u.toFixed(3),v:+o.v.toFixed(3),sx:+o.sx.toFixed(3),sy:+o.sy.toFixed(3),a:+o.a.toFixed(3)};if(o.p&&Object.keys(o.p).length){r.p={};for(const k in o.p)r.p[k]=+o.p[k].toFixed(2);}return r;});}
async function esaveDb(status){const cfg=ecfg();if(!cfg.some(o=>o.t==="hole")){emsg("Place the HOLE first (+ Add > Hole), then Lock again.");return;} const hw=(window.__lockCheck&&window.__lockCheck(cfg));if(hw){emsg(hw);return;}
 const io=$e("eio");if(io)io.value=JSON.stringify(cfg);try{navigator.clipboard.writeText(JSON.stringify(cfg));}catch(e){}   // always leave a paste-able copy as a safety net
 emsg("Saving "+cfg.length+" pieces\u2026");
 let db=null;try{db=window.__ppdb||(window.claude&&await window.claude.use("db"));}catch(e){}
 if(!db){emsg("Saved to clipboard \u2014 paste your layout to Claude in the chat.");return;}
 try{await db.doc("courses/"+COURSEID).set({config:cfg,status:status,at:Date.now()});
  emsg((status==="final"?"\uD83D\uDD12 Locked \u2713 ":"\u2713 Saved ")+COURSEID+" \u2014 tell Claude: \u201C"+(status==="final"?"lock ":"build ")+COURSEID+"\u201D");}
 catch(e){emsg("Save failed ("+(e&&e.code||"?")+") \u2014 layout is copied; paste it to Claude.");}}
function epalShow(){const el=$e("epal");if(el)el.classList.add("show");}
function epalHide(){const el=$e("epal");if(el)el.classList.remove("show");}
function applyHole(){{const t0=OBJS.find(o=>o.t==="tee");if(t0){tee={u:t0.u,v:t0.v};}}const h=OBJS.find(o=>o.t==="hole");if(!h)return;cup={u:h.u,v:h.v};
 const inMask=(pu,pv)=>{const px=Math.round(pu*IW),py=Math.round(pv*IW);if(px<0||py<0||px>=IW||py>=IH)return false;return MASK[py*IW+px]===1;};
 whirlR=Math.min(0.08,Math.max(0.016,h.sx||WHIRLR));for(;whirlR>0.016;whirlR-=0.002){let ok=true;for(let a=0;a<40;a++){const th=a/40*6.2832;if(!inMask(cup.u+Math.cos(th)*whirlR*1.04,cup.v+Math.sin(th)*whirlR*0.5*1.04)){ok=false;break;}}if(ok)break;}}
function eshowUI(edit){["ebar","eprops"].forEach(id=>{const el=$e(id);if(el&&id==="ebar")el.style.display=edit?"flex":"none";});
 ["top","tools","hud"].forEach(id=>{const el=$e(id);if(el)el.style.display=edit?"none":"";});
 const mb=$e("emode");if(mb)mb.textContent=edit?"\u25B6 Test":"\u270E Edit";
 if(!edit){const p=$e("eprops");if(p)p.style.display="none";epalHide();}else erefresh();}
function enterEdit(){EDIT=true;esel=-1;emode="";if(baseMask)MASK=baseMask.slice();cam.follow=false;cam.zoom=1;cam.cx=0.5;const _hv=(rect&&rect.h?(rect.h/2)/scl():0.4);cam.cy=Math.max(Math.min(_hv,(IH/IW)/2),Math.min((IH/IW)-_hv,tee.v-_hv*0.5));reset();eshowUI(true);}   /* open Edit looking at the TEE so the ball is on screen */
function enterTest(){if(!OBJS.some(o=>o.t==="hole")){emsg("Place the HOLE first, then Test.");epalShow();return;}EDIT=false;esel=-1;emode="";MASK=baseMask.slice();applyHole();carveSolids();cam.follow=true;cam.cy=(IH/IW)/2;reset();eshowUI(false);}
function wireEditor(){document.querySelectorAll("[data-eadd]").forEach(b=>b.onclick=()=>eadd(b.dataset.eadd));
 {const hq=$e("ghue2");if(hq){hq.value=Math.round(GHUE*100);hq.oninput=()=>{setHue(hq.value/100);const a=$e("ghue");if(a)a.value=hq.value;};}}
 let q;if(q=$e("eaddbtn"))q.onclick=()=>epalShow();if(q=$e("epalclose"))q.onclick=()=>epalHide();
 if(q=$e("emode"))q.onclick=()=>{if(EDIT)enterTest();else enterEdit();};
 if(q=$e("elock")){let armed=0;const lk=q;lk.onclick=()=>{const now=Date.now();if(now-armed<3000){armed=0;lk.textContent="🔒 Lock";esaveDb("final");}else{armed=now;lk.textContent="Tap again to lock ✓";emsg("Tap Lock again to finalize this course.");setTimeout(()=>{if(Date.now()-armed>=2900)lk.textContent="🔒 Lock";},3000);}};}
 if(q=$e("edup"))q.onclick=()=>{if(esel>=0){const o=JSON.parse(JSON.stringify(OBJS[esel]));o.u+=0.04;o.v+=0.04;OBJS.push(o);esel=OBJS.length-1;erefresh();}};
 if(q=$e("edel"))q.onclick=()=>{if(esel>=0){OBJS.splice(esel,1);esel=-1;erefresh();}};
 if(q=$e("eexp"))q.onclick=()=>{const s=JSON.stringify(ecfg());const io=$e("eio");if(io)io.value=s;try{navigator.clipboard.writeText(s);emsg("Copied "+ecfg().length+" pieces");}catch(e){emsg("Select the text below & copy");}};
 if(q=$e("eimp"))q.onclick=()=>{try{const a=JSON.parse($e("eio").value);if(Array.isArray(a)){OBJS=a.filter(o=>EPOOL[o.t]).map(o=>({t:o.t,u:+o.u,v:+o.v,sx:+o.sx,sy:+o.sy,a:+o.a,p:o.p||edefP(o.t)}));esel=-1;erefresh();emsg("Loaded "+OBJS.length);}}catch(e){emsg("Could not read that layout");}};}
if(document.readyState!=="loading")wireEditor();else addEventListener("DOMContentLoaded",wireEditor);
window.__ed=()=>({EDIT,n:OBJS.length,cup:{u:cup.u,v:cup.v},tee:{u:tee.u,v:tee.v},esel,whirlR});
window.__eadd=eadd;window.__etest=enterTest;window.__eedit=enterEdit;window.__esel=i=>{esel=i;};
window.__eobj=i=>Object.assign({},OBJS[i]);window.__escreen=i=>({x:toX(OBJS[i].u),y:toY(OBJS[i].v)});
