  const c2=_mix(col,[255,255,255],0.42);_flamePoly(bx,by,dx,dy,px,py,len,baseW,0.62,t,0.80);g.fillStyle="rgba("+c2[0]+","+c2[1]+","+c2[2]+",0.95)";g.fill();
  const cc=_mix(col,[255,255,255],0.72);_flamePoly(bx,by,dx,dy,px,py,len,baseW,0.30,t,0.84);g.fillStyle="rgba("+cc[0]+","+cc[1]+","+cc[2]+",0.98)";g.fill();
  g.restore();
