window.__lockCheck=(cfg)=>{const h=(cfg||ecfg()).find(o=>o.t==="hole");if(!h||!window.__onfairAt)return null;const rr=Math.min(h.sx||WHIRLR,(typeof holeR==="function"?holeR(h.u,h.v):0.05)),need=Math.max(0.026,rr*0.95);const t0=(cfg||ecfg()).find(o=>o.t==="tee");if(t0&&window.__onfairAt&&!window.__onfairAt(t0.u,t0.v)){for(var _sr=0.01;_sr<=0.05;_sr+=0.01){var _fnd=false;for(var _a=0;_a<12;_a++){var _th=_a/12*6.2832,_nu=t0.u+Math.cos(_th)*_sr,_nv=t0.v+Math.sin(_th)*_sr;if(window.__onfairAt(_nu,_nv)){t0.u=_nu;t0.v=_nv;_fnd=true;break;}}if(_fnd)break;}if(!window.__onfairAt(t0.u,t0.v))return "Move the ball onto the green, then Lock again.";}for(let a=0;a<8;a++){const th=a/8*6.2832;for(let d=0.008;d<=need;d+=0.008)if(!window.__onfairAt(h.u+Math.cos(th)*d,h.v+Math.sin(th)*d))return "Hole is too close to the wall — nudge it inward a little (the ball must roll over it, not bounce off the rim), then Lock again.";}return null;};

