window.__creepSteps=(u,v,dx,dy,pw)=>{ball={u,v};vel={x:dx*pw*PUTT,y:dy*pw*PUTT};sunk=false;sinking=false;sinkT=0;overhit=false;let i=0,creep=0,still=0;const H=1/60;for(;i<1800;i++){stepPhysics(H);if(sinking||sunk)break;const sp=Math.hypot(vel.x,vel.y);if(sp<SPK*0.25)creep++;else creep=0;if(sp<1e-4){still++;if(still>2)break;}else still=0;}return {creep,sunk,steps:i,restEd:Math.hypot((ball.u-cup.u)/whirlR,(ball.v-cup.v)/(whirlR*0.7))};};
