  ctx.fillStyle=grad("#2E8FA6","#7fd6ea",H*0.5,H);ctx.fillRect(0,H*0.5,W,H*0.5);ctx.strokeStyle="rgba(255,255,255,0.55)";ctx.lineWidth=1.5;for(var s2=0;s2<9;s2++){var sy=H*(0.56+s2*0.05),sx=(W*(s2*0.17)+t*14*(1+s2*0.1))%W;ctx.beginPath();ctx.moveTo(sx,sy);ctx.lineTo(sx+H*0.12,sy);ctx.stroke();}
