  ctx.fillStyle="#7E8A86";ctx.beginPath();ctx.moveTo(0,H);ctx.lineTo(0,H*0.42);ctx.lineTo(W*0.12,H*0.4);ctx.lineTo(W*0.22,H*0.5);ctx.lineTo(W*0.3,H*0.62);ctx.lineTo(W*0.36,H);ctx.closePath();ctx.fill();ctx.fillStyle="#9fb08c";ctx.beginPath();ctx.moveTo(0,H*0.44);ctx.lineTo(W*0.12,H*0.4);ctx.lineTo(W*0.2,H*0.48);ctx.lineTo(0,H*0.52);ctx.closePath();ctx.fill();
